CREATE TABLE public.bi_kpi_definitions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,code TEXT NOT NULL,name TEXT NOT NULL,description TEXT,domain TEXT NOT NULL,unit TEXT NOT NULL CHECK(unit IN('count','percentage','currency','duration','distance','weight','volume','score','ratio')),calculation_type TEXT NOT NULL,data_source TEXT NOT NULL,refresh_frequency TEXT NOT NULL CHECK(refresh_frequency IN('live','hourly','daily','weekly','monthly')),owner_role TEXT,target_direction TEXT NOT NULL CHECK(target_direction IN('higher','lower','range','informational')),active BOOLEAN NOT NULL DEFAULT true,version INTEGER NOT NULL DEFAULT 1,effective_date DATE NOT NULL DEFAULT CURRENT_DATE,UNIQUE(company_id,code));
CREATE TABLE public.bi_kpi_targets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,kpi_id UUID NOT NULL REFERENCES public.bi_kpi_definitions(id) ON DELETE CASCADE,scope_type TEXT NOT NULL CHECK(scope_type IN('company','branch','department','team')),scope_id UUID,target_value NUMERIC,warning_threshold NUMERIC,critical_threshold NUMERIC,effective_date DATE NOT NULL,end_date DATE,owner_id UUID REFERENCES auth.users(id),approval_status TEXT NOT NULL DEFAULT 'draft' CHECK(approval_status IN('draft','approved','rejected')),CHECK(end_date IS NULL OR end_date>=effective_date));
CREATE TABLE public.bi_kpi_snapshots(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,kpi_id UUID NOT NULL REFERENCES public.bi_kpi_definitions(id) ON DELETE CASCADE,scope_type TEXT NOT NULL,scope_id UUID,period_start TIMESTAMPTZ NOT NULL,period_end TIMESTAMPTZ NOT NULL,calculated_value NUMERIC,target_value NUMERIC,status TEXT NOT NULL CHECK(status IN('on_target','warning','critical','informational','unavailable')),calculated_at TIMESTAMPTZ NOT NULL DEFAULT now(),data_freshness TEXT NOT NULL,source_row_count INTEGER,calculation_version INTEGER NOT NULL DEFAULT 1,UNIQUE(company_id,kpi_id,scope_type,scope_id,period_start,period_end,calculation_version));
CREATE TABLE public.bi_saved_reports(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,name TEXT NOT NULL,domain TEXT NOT NULL,dataset_code TEXT NOT NULL,columns_config JSONB NOT NULL DEFAULT '[]',filters_config JSONB NOT NULL DEFAULT '[]',visibility TEXT NOT NULL CHECK(visibility IN('private','department','company','executive')),owner_id UUID REFERENCES auth.users(id),archived BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.bi_report_schedules(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,report_id UUID NOT NULL REFERENCES public.bi_saved_reports(id) ON DELETE CASCADE,frequency TEXT NOT NULL CHECK(frequency IN('daily','weekly','monthly','quarterly')),recipients_metadata JSONB NOT NULL DEFAULT '[]',delivery_format TEXT NOT NULL CHECK(delivery_format IN('csv','json','pdf_metadata','spreadsheet_metadata')),status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN('scheduled','generated','delivery_pending','delivery_failed','disabled')),last_generated_at TIMESTAMPTZ,next_due_at TIMESTAMPTZ,active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE public.bi_report_commentary(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,report_id UUID REFERENCES public.bi_saved_reports(id) ON DELETE SET NULL,commentary_type TEXT NOT NULL CHECK(commentary_type IN('executive','department','variance','corrective_action')),body TEXT NOT NULL,owner_id UUID REFERENCES auth.users(id),reviewed_by UUID REFERENCES auth.users(id),approved_by UUID REFERENCES auth.users(id),sign_off_date DATE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.bi_audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,entity_type TEXT NOT NULL,entity_id UUID NOT NULL,event_type TEXT NOT NULL,actor_id UUID REFERENCES auth.users(id),metadata JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['bi_kpi_definitions','bi_kpi_targets','bi_kpi_snapshots','bi_saved_reports','bi_report_schedules','bi_report_commentary','bi_audit_logs'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t);EXECUTE format('GRANT ALL ON public.%I TO service_role',t);EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (public.has_any_role(company_id,ARRAY[''admin'',''operations_manager'',''finance_manager'',''fleet_manager'',''warehouse_manager'',''hr_manager'',''compliance_manager'',''procurement_manager'',''department_manager'',''viewer'']::public.app_role[]))',t||'_read',t);END LOOP;END $$;
